import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Rhinocs_%E4%BB%95%E6%A7%98%E6%A4%9C%E8%A8%8E.html","title":"Rhinocs_仕様検討","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":5.48,"words":1643},"filePathRelative":"Rhinocs_仕様検討.md"}`),a={name:`Rhinocs_仕様検討.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="rhinocs-仕様検討" tabindex="-1"><a class="header-anchor" href="#rhinocs-仕様検討"><span>Rhinocs_仕様検討</span></a></h1><p><a href="./Rhinocs.html">Rhinocs</a>の仕様の検討を残しておく。</p><h2 id="続-インテントまわりの検討-2026-11-09-月" tabindex="-1"><a class="header-anchor" href="#続-インテントまわりの検討-2026-11-09-月"><span>続: インテントまわりの検討 2026-11-09 (月)</span></a></h2><p>前回無理という結論になったが、やはり<a href="./TeFWiki.html">TeFWiki</a>やファイラーから開けないと不便、という事で対応する。 前回の調査を元に対応するのは以下。</p><ul><li>ACTION_EDIT</li><li>ACTION_VIEW+writable</li></ul><p>そしてインテントに来る全てのURLはPersistableではない、という前提で扱う。</p><p>find_file_hookにisTempの引数を追加し、これがtrueの時はpersistableではない、とする。 これまでのコードは変更したくないのでundefinedならpersistable。</p><p>Tetra Freeがjsはapplication/javascriptで投げてくるので対応するMIME typeは <code>text/*</code> と application/javascriptとした。</p><h2 id="インテントまわりの検討-2026-09-11-金" tabindex="-1"><a class="header-anchor" href="#インテントまわりの検討-2026-09-11-金"><span>インテントまわりの検討 2026-09-11 (金)</span></a></h2><p>ACTION_EDITはuriは一時的で、送り側がFLAG_GRANT_PERSISTABLE_URI_PERMISSIONをつけてる場合に限りあとからも使える。 ACTION_OPEN_DOCUMENTなどは普通はtakePersistableUriPermission出来る。</p><p>一時的なpermissionのuriをfind_file_hookなどで保存してあとから使うと使えない訳だよなぁ。 この辺は</p><ul><li>一時的 <ul><li>read only</li><li>writable</li></ul></li><li>永続的に使える <ul><li>read only</li><li>weritable</li></ul></li></ul><p>の4通りのurlを本来は区別する必要がある。</p><p>ただこの変更はちょっと大掛りなので、とりあえずwritableで永続的に使える時だけ開ける、とするかなぁ。</p><p>試しにこの方針で実装してみたらFLAG_GRANT_PERSISTABLE_URI_PERMISSIONをつけている人はほとんのいないっぽいいので意味がない。 という事でちゃんと対応しない限りはintentは受けとらない方がいいか。</p><h2 id="行のリスト的なインターフェース-2026-06-20-土" tabindex="-1"><a class="header-anchor" href="#行のリスト的なインターフェース-2026-06-20-土"><span>行のリスト的なインターフェース 2026-06-20 (土)</span></a></h2><p>ここまで割とemacs lispやxyzzyに似たインターフェースを用意してきたが、 バッファ全体の変更はmapとか使って行単位のリストとして処理出来る方がJS的かな、と思う。</p><p>この時にundoバッファをどうするか？という問題があるが、全部テキストを保存していくのもやりすぎかなぁ。 本当は行の差分からreplaceでの表現を作り出せると良いのだが。 ちょっと難しそうなので、単に変更の行だけまるごと保存、くらいでいいかもしれない。</p><p>まずはバッファを行のリストとして取り出す、<code>selected_buffer_lines()</code>を提供する。 そして結果として行のリストを渡して置換とみなす、<code>bulk_replace(lines)</code>を提供するとどうだろう？</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> lines <span class="token operator">=</span> <span class="token function">selected_buffer_lines</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token parameter">l</span><span class="token operator">=&gt;</span> <span class="token punctuation">{</span> <span class="token comment">/* 何か正規表現で置換とか */</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">bulk_replace</span><span class="token punctuation">(</span>lines<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一度変数に入れないといけないのはダサいが、JSではそうするものだとgeminiが言ったのでこれでいいかな。</p><p>行単位でMyers diffを計算するのがいいかもしれん。</p><p><a href="https://developer.android.com/reference/androidx/recyclerview/widget/DiffUtil" target="_blank" rel="noopener noreferrer">DiffUtil \xA0-\xA0 API reference \xA0-\xA0 Android Developers</a> こんなのあるんか！</p><p><a href="https://android.googlesource.com/platform/frameworks/support/+/refs/heads/androidx-main/recyclerview/recyclerview/src/main/java/androidx/recyclerview/widget/DiffUtil.java#236" target="_blank" rel="noopener noreferrer">recyclerview/recyclerview/src/main/java/androidx/recyclerview/widget/DiffUtil.java - platform/frameworks/support - Git at Google</a>　areItemsTheSameでスネークを実行するので、これは文字列のイコールを返すべきっぽいな。</p><h3 id="api名の検討" tabindex="-1"><a class="header-anchor" href="#api名の検討"><span>API名の検討</span></a></h3><p>get_buffer_linesにしようかと思ったが、selected_bufferと一貫性がないと思ったのでその検討のメモ。</p><p>elispだと現在のバッファはcurrent_bufferで、現在のウィンドウはselected_window。 これは一貫性がない気がしていて、xyzzyはselected_bufferなので、Rhinocsはselected_bufferにしている。</p><p>その理屈でいけばselected_lines()とかcurrent_linesの方が良いのだろうが、 selected_linesはいかにも現在選択中の行を返しそうだし、currentも現在のカーソル位置に関連したものがかえってきそうでややこしい。</p><p>単にBufferのAPIにしておく方がいいかもしれない。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> lines <span class="token operator">=</span> <span class="token function">selected_buffer</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">getLines</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token parameter">l</span><span class="token operator">=&gt;</span><span class="token punctuation">{</span><span class="token comment">/* 何か処理 */</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">bulk_replace</span><span class="token punctuation">(</span>lines<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>こっちの方がいいか。selected_buffer_linesとかの関数はラッパとして提供してもいい気もするが。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> lines <span class="token operator">=</span> <span class="token function">selected_buffer_lines</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">                <span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token parameter">l</span><span class="token operator">=&gt;</span><span class="token punctuation">{</span><span class="token comment">/* 何か処理 */</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token function">bulk_replace</span><span class="token punctuation">(</span>lines<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>selected_buffer, selected_windowの流れからすればこんな感じか。 get_buffer_linesとselected_bufferは一貫性が無いな。</p><p>buffer_substringとの関連でいけばbuffer_linesとかの方がいいかもしれないが、第三引数無しだと暗号的なのでslected_buffer_linesにしておこう。</p><p>bulk_replaceの方はちょっと悩ましい。</p><p>replace-matchとかがemacs lispとかなので、replace_bulkの方が正しいのだが、目的語じゃないしなぁ。</p><p>replace_new_linesとかの方がただしいのだろうが、長いわりには挙動がわかりにくいしな。 という事でbulk_replaceのままにしておく。</p><p>勝手に差分がundoバッファに入る感じで。</p><h2 id="ファイラーに必要なapi-2026-06-06-土" tabindex="-1"><a class="header-anchor" href="#ファイラーに必要なapi-2026-06-06-土"><span>ファイラーに必要なAPI 2026-06-06 (土)</span></a></h2><p>JS側で実装するために必要な低レベルAPIを考える。</p><ul><li><code>select_open_dir_callback(success, fail, fromDirUri=undefined)</code></li><li><code>open_dir(uri)</code></li></ul><p>１つ目はFastFileのdirを返す。二つ目はuriからFastFileのdirを作る。</p><p>FastFileはlistFiles()を呼べばファイルの一覧が取れるし、getUri()やgetName()で保存するようなデータをとれる。</p><p>uriを保存したら、そのuriからFastFileを復元する必要がありそうなのでopen_dirを作る。</p><p>こうして考えるとselect_open_fileなどもFastFileを返すべきだな。直そう。</p><h2 id="インクリメンタルサーチ-2026-06-03-水" tabindex="-1"><a class="header-anchor" href="#インクリメンタルサーチ-2026-06-03-水"><span>インクリメンタルサーチ 2026-06-03 (水)</span></a></h2><p>SKKが途中をinsertする都合で、unmatchのケースをemacsとかよりもシームレスに扱いたい。 そこでVSCodeのようにするかなぁ、と思う。</p><ul><li>検索単語が変更されたらいつも現在の位置に戻ってマッチ</li><li>wrapも自動で行う</li></ul><h2 id="floating-list-2026-05-27-水" tabindex="-1"><a class="header-anchor" href="#floating-list-2026-05-27-水"><span>floating-list 2026-05-27 (水)</span></a></h2><p>switch-bufferはタブ補完みたいなのよりはVSCodeのCmd+pみたいなのにしたい。フィルタリングとかはJS側で書くとする。 するとエディタ側で用意すべきものは何なのかを考えたい。</p><p>とりあえず以下があれば実現は出来るか？</p><ul><li>文字列のリストをセットするとそれを下から上のリストとして描画し、一番下が選択される</li><li>選択を一つ上、一つ下に移動するコマンド</li><li>現在の選択を返す関数</li></ul><p>そもそもfloatingListインスタンスが取れればあとはJS側からこれを操ればいいか？</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">let floating = get_floating_list();</span>
<span class="line">floating.items = [&quot;abc&quot;, &quot;def&quot;, &quot;ghi&quot;];</span>
<span class="line">floating.moveUp();</span>
<span class="line">floating.moveDown();</span>
<span class="line">let res = floating.selectedIndex</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>実装して試したら良さそうだったのでこれで行く。</p><h2 id="switch-to-buffer-2026-05-27-水" tabindex="-1"><a class="header-anchor" href="#switch-to-buffer-2026-05-27-水"><span>switch-to-buffer 2026-05-27 (水)</span></a></h2><p>メモリ上にあるバッファを探すというのはAndroid的ではない気もする。 リサイクルで全部無くなっちゃうので。</p><p>現状の手抜きfile_historyではuriとファイル名を保存しているが、 むしろこのデータから探す方がAndroid的ではないか？ そしてメモリ上にあればそれを使ってなければファイルからロードする、 という風にメモリの方をキャッシュ的に使えば、メモリにある間はemacsっぽくも振る舞う。</p><p>ようするにget-buffer-createにurlでとってくるものがあればいいようにも思う。</p><p>バッファ名 ＞ ヒストリ ＞ uri ＞ switch-buffer-by-uri</p><p>となればメモリに無くても動く気がするな。 あ、これだと保存してないバッファが引っかからないな。 もう一捻り必要そうだが、路線は悪くない気がする。 先にメモリ上を探して、なければヒストリを探すのがいいか。</p><p>こうヒストリをコアな機能に使うと、 ヒストリが現状js側で勝手に実装している独自拡張なのがどうなんだ、という気もするが。</p><p>まぁこの辺はエディタはJS側で実装するのに必要な最小限の機能を実装するだけにしてJS側でいろいろやるようにしておくかな。 第三者が試すのが難しくなるが、しばらくは自分のことだけ考えるのが今風だろう。</p><h2 id="ファイルの新規作成の仕様検討" tabindex="-1"><a class="header-anchor" href="#ファイルの新規作成の仕様検討"><span>ファイルの新規作成の仕様検討</span></a></h2><p>SAFではファイルを開くのと新規作成ではリクエストが別なので、 find_fileで無かったら作成というemacs的な挙動とは異なる。 無理にemacsっぽくしようと思えば実現は出来るのだが、 それよりは、よりSAFに自然な仕様にしておきたい。</p><p>考えているのは、新規作成のようなコマンドを作り、 するとVSCodeとかのuntitledみたいな扱いのバッファが出来る感じにして、 それをC-x C-sするとSAF的には新規作成と扱う、という挙動。 これならsave-asと同じコードに出来るし、SAF的にも自然だし、 VSCodeなどの昨今のエディタに慣れている人からすれば自然に思う。</p><p>emacs的では無いが、ファイル回りはSAFに寄せるほうがいい気もしている。</p><p>当初はfind_fileももっとemacsっぽく実装しようと思っていたが、そのためにはディレクトリのpermissionをもらう必要がある。 それは結構ややこしい仕様だよなぁ、という気はしてた。</p><p>その辺が面倒なので、現状はとりあえずSAFでファイルを単体で開いていて、 選ぶファイルの選択はシステムのファイルマネージャーを使っていて、 あとで書き直そうと思っていたが、使っていると、今のこの挙動の方がAndroid的で良い気はしてきている。</p><p>システムのファイルマネージャーは使いづらいけど、 ブックマークとかヒストリを充実させたり、 あとでファイラーっぽいものをJSレイヤーで書いたりする方がいいような気がしてきている。</p><p>emacsと変えると学習コストとかドキュメントとかの問題が出てくるけれど、 中途半端に似せようとして分かりにくいよりはAndroid的に自然にしておく方が将来困ったことにもなりにくい気がする。</p><p>C-x C-nでUntitiled-1とかのバッファが出来て、それをC-x C-sで保存する時に名前を指定する、 という感じにしたい。</p><h3 id="new-fileなのnew-bufferなのか-new-fileにする" tabindex="-1"><a class="header-anchor" href="#new-fileなのnew-bufferなのか-new-fileにする"><span>new_fileなのnew_bufferなのか（new_fileにする）</span></a></h3><p>実際にバッファを作るのだからnew_bufferが正しいようにも思う。 だがnew_bufferはバッファを作るだけでwindowにセットするのは分けたいようにも思う。</p><p>VSCodeなどではNew Text Fileに相当する挙動なので、保存しなくてもnewというのはVSCodeとは同じであるし、 find-fileのnew版と考えるとnew_fileでもいい気もする。</p><p>どれもいまいちという気がするがとりあえずnew_fileにする。</p><h2 id="ミニバッファの仕様検討" tabindex="-1"><a class="header-anchor" href="#ミニバッファの仕様検討"><span>ミニバッファの仕様検討</span></a></h2><p>ミニバッファはxyzzyやemacsやlemでは、割とモーダルっぽく内部でループを回す感じの実装になっている。 そちらの方がトラブルが無かったのだろうが、SKKとかとは相性が悪そうだしJS的でもない。</p><p>という事でもう少し低レベルのAPIを提供してJavaScriptのレイヤーでプロミスで実装する感じを目指したい。</p><h3 id="低レベルapi" tabindex="-1"><a class="header-anchor" href="#低レベルapi"><span>低レベルAPI</span></a></h3><p>以下の２つを提供する。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">enter_minibuffer</span><span class="token punctuation">(</span><span class="token parameter"><span class="token literal-property property">prompt</span><span class="token operator">:</span> string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ミニバッファとミニバッファWindowを用意してそれをアクティブにする。promptはミニバッファの先頭に表示されるラベル。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">leave_minibuffer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> string<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ミニバッファとミニバッファWindowを破棄し、その前にアクティブだったWindowとバッファにフォーカスを戻す。 ミニバッファに入力されている文字列を返す。</p><p>これらを使ってJS側で通常のミニバッファ系列の関数を実装する。</p><h3 id="js側での実装" tabindex="-1"><a class="header-anchor" href="#js側での実装"><span>JS側での実装</span></a></h3><p>まずはemacs lispのread-string相当を実装する。</p><p><a href="https://web.sfc.wide.ad.jp/~sagawa/gnujdoc/elisp-manual-20-2.5/elisp-ja_20.html#SEC265" target="_blank" rel="noopener noreferrer">GNU Emacs Lispリファレンスマニュアル: Minibuffers</a></p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">function</span> <span class="token function">read_string</span><span class="token punctuation">(</span><span class="token parameter"><span class="token literal-property property">prompt</span><span class="token operator">:</span> string</span><span class="token punctuation">)</span> <span class="token operator">:</span> Promise<span class="token operator">&lt;</span>string<span class="token operator">&gt;</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>promptでミニバッファを表示して入力を受け取り、結果のPromiseを返す。</p><p>これはminibuffer keymapをpushしてenter_minibuffer()して、 Promiseを返し、このキーマップでReturnだったらこのPromiseをresolve、C-gだったらrejectするような感じの実装になる。</p><h3 id="デバイスごとの保存-2026-05-21-木" tabindex="-1"><a class="header-anchor" href="#デバイスごとの保存-2026-05-21-木"><span>デバイスごとの保存 2026-05-21 (木)</span></a></h3><p>Rhinocsはなるべく見えない所（data下）にものを保存しない、をコンセプトにしているが、これだとファイルのヒストリのような、デバイスごとに保存したいものをjsから保存する時にsyncthingで共有されてしまって困る。</p><p>デバイスごとのIDは簡単にはとれなさそうなので、手動で設定する事にしたい。</p><p>APIとしてはSharedPreferenceに文字列を読み書き出来ればいいだろう。それを使ってデバイスごとに一回手動で <code>set_device_id(&quot;BOOX&quot;)</code> とかをevalする感じにすればいいかな、と思っている。</p><p>すると、 <code>/storage/per_device/BOOX/file_history/history.json</code> とかに保存する感じになればいいだろうか。</p><p><code>get_per_device_storage_dir()</code>とかで取れればいいかな。storageって名前がいまいちだな。なんかいい名前あるだろうか？でもstoreではplay storeと被るしなぁ。 storageでいいか。</p><p>結局、以下を実装した。</p><ul><li>join_path</li><li>put_pref_string</li><li>get_pref_string</li><li>set_device_id</li><li>get_device_id</li><li>get_per_device_storage_dir</li></ul><h2 id="モード行の仕様検討" tabindex="-1"><a class="header-anchor" href="#モード行の仕様検討"><span>モード行の仕様検討</span></a></h2><p>emacsやxyzzyはmode-line-format変数に設定しておくと毎回それをformatして表示するが、RhinoだといちいちContextをenterして値を取り出すのでなんか無駄な気はする。</p><p>それよりは以下みたいな関数で設定してWindowに持たせるかな。</p><ul><li><code>set_mode_line_format(fmt: string)</code></li><li><code>get_mode_line_format() : string</code></li></ul><p>mode-line-formatの％の略語は今どき覚える気も起こらないので、冗長にドル始まりの変数名っぽいのでいいだろう。 JavaScriptのテンプレート文字列っぽい以下の表記でどうか？</p><ul><li><code>\${column}</code></li><li><code>\${lineNum}</code></li><li><code>\${bufferName}</code></li><li><code>\${modified}</code></li></ul><p>とりあえずこの4つくらいサポートする事から始めたい。modifiedは変更されてると**でそれ以外は--とする。read onlyとかはしばらく考えない。</p><p>例えば以下みたいな感じで指定する。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token function">set_mode_line_format</span><span class="token punctuation">(</span><span class="token string">&quot;--\${modified}- \${bufferName} Ln: \${lineNum} Col: \${column} --&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>get_mode_line_formatでは置換される前のfmt文字列がそのまま取れる。</p><h3 id="モード行はアプリで一つとする" tabindex="-1"><a class="header-anchor" href="#モード行はアプリで一つとする"><span>モード行はアプリで一つとする</span></a></h3><p>モード行はemacsなどはバッファローカルでそれはモードがバッファローカルだからなのだが、するとSKKとかもモードとして実装する方が自然になる。 だがそれが望ましいかというと割と微妙。 そもそもモードがいるのか？というのはちょっと微妙なので、必要になるまではやらなくてもいいかな？という気もする。</p><p>結局拡張していけるプラットフォーム的なものを作りたいのか、あくまでエディタだけに特化したいのか、という問いで、 今必要なのはエディタなので、まずはエディタに特化していきたい。</p><p>モード行に相当するものはVSCodeではアプリで一つでアクティブなバッファ（ウィンドウ）の情報が表示されている。 こっちの方がスペースも食わないしいいような気もする。</p><p>モードが無いならそれはモード行ではないのでは？という気もするが、とりあえず関数などの名前はemacsに寄せておく。</p><h2 id="マーカー仕様検討-2026-05-20-水" tabindex="-1"><a class="header-anchor" href="#マーカー仕様検討-2026-05-20-水"><span>マーカー仕様検討 2026-05-20 (水)</span></a></h2><p>eval-regionやコピペのためにマーカーが欲しくなる。既存実装を調査＞<a href="./エディタ調査.html">エディタ調査</a></p><p>elipsの関数名を参考に考える。</p><p><a href="https://web.sfc.wide.ad.jp/~sagawa/gnujdoc/elisp-manual-20-2.5/elisp-ja_31.html#SEC473" target="_blank" rel="noopener noreferrer">GNU Emacs Lispリファレンスマニュアル: Markers</a></p><p>マーク的なものは最小限にして基本的にはマーカーのみを揃える感じで。しばらくmark-ringとかはやらない。 以下を用意するか。</p><ul><li>mark_marker</li><li>set_marker</li><li>marker_position</li></ul><p>mark関連の唯一の関数がmark_marker。 make_markerはしばらく提供せず、mark_markerで唯一のmarkerを取得する感じにする。 markなどはmark-markerとmarker-positionなどを使ってjsレイヤーで実装する。</p><p>この３つを実装するには以下をすればいいか。</p><ol><li>Bufferにmarkerのリストをぶら下げる</li><li>insertとかdeleteとか必要な所でadjustの実装を追加</li><li>js側に見せるメソッドを追加</li></ol><h2 id="リサイクルとenv" tabindex="-1"><a class="header-anchor" href="#リサイクルとenv"><span>リサイクルとenv</span></a></h2><p>Androidはプロセスが殺されるので、インタープリタをずっと活かしておく、という事が出来ない。 だから殺されて再生成された時にまぁまぁの速度で動く必要がある。</p><p>emacsのようにすべてをメモリ上にずっと置いておく、という前提は難しいので、恐らく現在のバッファに対して読み込まなくてはいけないものをある程度は限定する必要はありそう。</p><p>また、再生されてから動き出すまでと、その裏でいろいろやるのは分離したい。SKKの初期化などはいかにも分離したいよなぁ。</p><h2 id="viewについての雑記" tabindex="-1"><a class="header-anchor" href="#viewについての雑記"><span>Viewについての雑記</span></a></h2><p>下の方に書いたように初期はスクロールを真面目にやろうと考えていたが、それはドッグフードまでが遠すぎてやる気が出ない。 もっと単純にしよう。</p><p>Viewはバッファのある範囲を書くが、コンソールっぽく単純化したい。 Viewのうち文字を書く領域をPaneと呼ぶ事にする。</p><p>Paneは縦横の文字のグリッドで、文字は幅が1か2のどちらかとする。フォントは等幅フォント固定。 文字の描画は文字ごとに書く。くっついたりする言語とかはサポートしないし、文字の幅を足したものが文字列の幅になるようにする。</p><p>バッファに対してある行の範囲を指定すると、その範囲でのGrid情報を計算して、rowとcolを指定すると文字が取り出せる（または前のcolが2幅なら無しが取り出せる）。 この情報はGridと呼ぶ事にするか。</p><p>PaneはGridの通りに文字を描くだけとする。スクロールとかもとりあえずは考えずに全部redrawとする。</p><h2 id="guiスレッドとrhinoのスレッド" tabindex="-1"><a class="header-anchor" href="#guiスレッドとrhinoのスレッド"><span>GUIスレッドとRhinoのスレッド</span></a></h2><p>とりあえずGUIスレッドでRhinoも動かす。これでは駄目なのは少し考えればわかるが、Bufferの更新とUIのレンダリングの同期がちょっと面倒なので、まずは同一スレッドで始める。</p><p>最終的にはRhinoは専用の一つのスレッドでいつも動かし、GUI側にはイベントで変更を通知し、Gridを生成する時にはBufferをロックする感じにしたい。</p><h2 id="パッケージについて" tabindex="-1"><a class="header-anchor" href="#パッケージについて"><span>パッケージについて</span></a></h2><p>最初にホームディレクトリを指定させる。これはSAFで。とりあえずそこにjsのスクリプト置いて、それをロードする感じでいってみたい。 本当にそれでエディタになるのかは少し自信が無い所もあるが、 カスタマイズしたい訳では無いので、既存のパッケージの関数の上書きとかはまずは出来なくてもいいだろう。 どちらかといえば途中からは実装をRhino側でやるようにしたいなぁ、という気持ちが強い。</p><p>ただActivityのリサイクルがあるので、あまり大きな初期化を最初にやる、というモデルは厳しいかもしれない。</p><h2 id="バッファについて" tabindex="-1"><a class="header-anchor" href="#バッファについて"><span>バッファについて</span></a></h2><p>バッファは行のリストで。ギャップは入れないで単純に毎回コピーする。 バッファ周りはAPIは割と真面目に作る。 StringBuilderのArrayListくらいから始めるか。</p>`,142)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};